const listHtmlFiles = async (directory) => {
  const entries = await readdir(directory, { withFileTypes: true });
  const nested = await Promise.all(entries.map(async (entry) => {
    if (entry.name === '.git' || entry.name === 'ru' || entry.name === 'uk' || entry.name === 'en' || entry.name === 'node_modules') return [];
    const entryUrl = new URL(`${entry.name}${entry.isDirectory() ? '/' : ''}`, directory);
    if (entry.isDirectory()) return listHtmlFiles(entryUrl);
    return entry.name.endsWith('.html') ? [entryUrl] : [];
  }));
  return nested.flat();
};

